/**
 * 「图形与几何」模块知识点数据（人教版初中数学）。
 *
 * 用途：为「学而」学习 App 的数学模块提供图形与几何领域的完整内容 ——
 *   七上几何图形初步、七下相交线与平行线、七下平面直角坐标系、八上三角形、
 *   八上全等三角形、八上轴对称、八下勾股定理、八下平行四边形、九上旋转与中心对称、
 *   九上圆、九下相似三角形、九下锐角三角函数、九下投影与视图，
 *   以及贯穿初中三年的「几何证明常见错误与辅助线」专题（跨学段综合）。
 *
 * 数据约定：
 *   1. `tex` 字段是 KaTeX 源码，不加 `$`；文字字段（concepts、examples、pitfalls、methods 等）
 *      里的行内公式一律用 `$...$` 包裹，交给渲染器处理。
 *   2. 几何内容**必须图形结合**：图用 `figure`（`PhysicsFigure` 的图元，0—100 画布单位）
 *      画出来，而不是只在文字里描述关系。概念、例题、系统讲解都尽量配图——
 *      「△ABC≌△DEF 的对应关系」「SAS 的角是夹角」这类话，配上图一眼就懂，只有文字则学生
 *      得自己在脑子里画。图必须写 `alt`（朗读与检索要用），不要写占位图。
 *   3. 概念条目一律点明「判定」与「性质」的区别；易错点写真实高频错误，不写套话。
 *   4. 每条概念除定义（`explain`）外，尽量补一段解析（`insight`）：定义只说「是什么」，
 *      解析说「为什么这样规定、用的时候怎么想、方向会不会用反」。
 *   5. 题干与解析中的几何符号统一用 KaTeX 写正确：$\triangle$、$\angle$、$\parallel$、
 *      $\perp$、$\cong$、$\sim$、$^\circ$。
 */

